import {createServer} from 'node:http';
import {readFile} from 'node:fs/promises';
const port=Number(process.argv[2]);if(!Number.isInteger(port)||port<1024||port>65535)throw new Error('Supply an owned disposable local port.');
const page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Offline attachment storage verification</title><style>body{font:16px system-ui;max-width:60rem;margin:2rem auto;padding:1rem}pre{white-space:pre-wrap;overflow-wrap:anywhere}button{margin:.5rem}button:focus-visible{outline:3px solid #125bcc;outline-offset:3px}li{margin:.75rem 0}</style><main><h1>Offline attachment storage verification</h1><p>Disposable native IndexedDB and Web Locks. Controlled client transports; this page does not prove native server authorization or interactive browser acceptance.</p><pre id="report" role="status" data-status="running">Running native browser storage checks…</pre><ol id="results"></ol><div id="view"></div></main><script type="module" src="/fixture.js"></script></html>';
const server=createServer(async(req,res)=>{try{const pathname=new URL(req.url,'http://127.0.0.1').pathname;let bytes,type;if(pathname==='/'){bytes=page;type='text/html';}else if(pathname==='/fixture.js'){bytes=await readFile(new URL('./offline-attachments-browser-client.mjs',import.meta.url));type='text/javascript';}else if(/^\/runtime\/[a-z0-9-]+\.js$/u.test(pathname)){bytes=await readFile(new URL('../../dist/'+pathname.slice(9),import.meta.url));type='text/javascript';}else{res.writeHead(404);res.end();return;}res.writeHead(200,{'content-type':type+'; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'});res.end(bytes);}catch{res.writeHead(500);res.end('Owned fixture unavailable.');}});
server.listen(port,'127.0.0.1',()=>console.log('Owned attachment storage fixture http://127.0.0.1:'+port));
for(const signal of ['SIGINT','SIGTERM'])process.once(signal,()=>server.close(()=>process.exit(0)));
